<script setup lang="ts">import{onMounted,ref,computed}from 'vue';import{useRoute}from 'vue-router';import{lab,load}from '../stores/research';import{canEdit}from '../stores/auth';import*as sensitivities from '../api/sensitivities';import{useTask}from '../hooks/useTask';import{usePolling}from '../hooks/usePolling';import{fmt,ratio}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import CorrectionCard from '../components/CorrectionCard.vue';const route=useRoute(),baseRun=ref(Number(route.query.run)||0),swapLimit=ref(1),name=ref('稀疏层 · 固定边际互换敏感性复核'),notice=ref(''),selected=ref<number|null>(null),detail=ref<Awaited<ReturnType<typeof sensitivities.detail>>|null>(null),{error,busy,execute}=useTask();const result=computed(()=>detail.value?.status==='completed'?detail.value.result||null:null);const labels:Record<string,string>={higher:'A更高',lower:'A更低',equal:'无差别',undefined:'未定义'};const rows=computed(()=>lab.sensitivities);
async function loadOne(id:number){const d=await sensitivities.detail(id);if(selected.value===id)detail.value=d}
function inspect(id:number){selected.value=id;detail.value=null;execute(()=>loadOne(id))}
onMounted(()=>execute(async()=>{await load();baseRun.value=baseRun.value||lab.runs.find(r=>r.status==='completed')?.id||0;const wanted=Number(route.query.sensitivity)||lab.sensitivities.find(r=>r.status==='completed')?.id||0;if(wanted)await inspect(wanted)}));
usePolling(()=>{if(detail.value&&['queued','running'].includes(detail.value.status))execute(async()=>{await loadOne(detail.value!.id);await load()})});
function submit(){execute(async()=>{const r=await sensitivities.create({name:name.value,run_id:baseRun.value,swap_limit:swapLimit.value});await load();notice.value=`敏感性复核 #${r.id} 已冻结，等待独立worker计算`;inspect(r.id)})}
function download(id:number){execute(()=>sensitivities.exportCsv(id))}</script>
<template><PageHeading index="06" title="少量误判，会不会改写结论。" text="冻结原研究的四格与阈值，只在每层固定边际内互换成功/失败，枚举全部可行修正；原研究不变。"/><ErrorNotice :message="error" @retry="execute(load)"/><p v-if="notice" class="success" role="status">{{notice}}</p><div class="configure-grid"><form v-if="canEdit" @submit.prevent="submit"><label>原冻结研究<select v-model.number="baseRun" aria-label="原冻结研究"><option v-for="r in lab.runs.filter(r=>r.status==='completed')" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><label>敏感性复核名称<input v-model="name" minlength="3" maxlength="160" required/></label><label>每层最多互换对数<input v-model.number="swapLimit" type="number" min="0" max="500" step="1" required/></label><p class="margin-note">k&gt;0 表示把B的一次成功改为A成功、把A的一次失败改为B失败；k&lt;0 反向。每层总数与行列边际不变，|k|≤上限。组合数超过200000时拒绝冻结。</p><button class="primary" :disabled="busy||!baseRun">冻结修正范围并送入队列 →</button></form><aside><p class="eyebrow">FIXED MARGINS / ENUMERATED CORRECTIONS</p><h2>不是重算，<br>是核对结论的脆弱处。</h2><p>共同OR、CMH与均值距离双侧精确p逐项重算，但输入仍来自原研究的冻结快照。</p><p>稀疏层的单个误判就可能改变OR方向或p值；枚举结果只说明敏感性，不构成新的确证证据。</p><p>复核说明与获批CSV回读同一份冻结结果，不重跑枚举。</p></aside></div><section class="run-ledger"><h2>敏感性复核档案</h2><article v-for="r in rows" :key="r.id"><div><span>#{{r.id}}</span><h3>{{r.name}}</h3><small>原研究 #{{r.base_run_id}} · 每层≤{{r.swap_limit}} · 指纹 {{r.base_fingerprint.slice(0,12)}}…</small></div><StatusBadge :status="r.status"/><button class="text-button" @click="inspect(r.id)">读取冻结结果 ↗</button></article><p v-if="!rows.length" class="empty">尚无敏感性复核；先完成一份原研究，再冻结修正范围。</p></section><template v-if="detail"><div v-if="detail.status==='failed'" class="empty"><h2>敏感性复核未完成</h2><p>{{detail.error}}</p></div><div v-else-if="!result" class="empty"><h2>正在枚举固定边际修正</h2><p>状态会自动更新；结果只来自服务端冻结快照。</p></div><template v-else><div class="result-byline"><b>#{{detail.id}} / {{detail.name}}</b><span>原研究 #{{detail.base_run_id}} {{detail.base_name}} · α={{result.alpha}} · 每层≤{{result.swap_limit}}</span><span v-if="detail.status==='completed'" class="actions"><button class="outline" @click="download(detail.id)">下载敏感性CSV ↗</button></span></div><div class="result-totals"><div><small>可行修正组合</small><b>{{result.capacity.combination_count.toLocaleString('zh-CN')}} <span>/ 上限{{result.capacity.combination_cap.toLocaleString('zh-CN')}}</span></b></div><div><small>共同OR方向翻转</small><b class="p-value">{{result.direction.flip_count}} <span>/ {{result.capacity.combination_count}}</span></b></div><div><small>精确p 最小 / 最大</small><b>{{result.exact_p.min.value.display}} <span>/ {{result.exact_p.max.value.display}}</span></b></div><div><small>CMH 最小 / 最大</small><b>{{fmt(result.cmh.min.value,6)}} <span>/ {{fmt(result.cmh.max.value,6)}}</span></b></div></div><div class="results-split"><section><h2>方向：原结论落在哪一侧。</h2><dl><div><dt>原研究方向</dt><dd>{{labels[result.direction.baseline]}}（{{ratio(result.baseline.adjusted_or)}}）</dd></div><div v-for="k in ['higher','lower','equal','undefined']" :key="k"><dt>{{labels[k]}}</dt><dd>{{result.direction.counts[k as keyof typeof result.direction.counts]}} 个组合</dd></div><div><dt>方向改变（含变为无差别）</dt><dd>{{result.direction.changed_count}}</dd></div><div><dt>方向翻转（更高 ↔ 更低）</dt><dd>{{result.direction.flip_count}}</dd></div></dl><p class="plot-caption">翻转指共同OR从原方向的A更高/更低跨到相反方向；无差别（OR=1）与未定义单列。</p></section><aside class="evidence-note"><p class="eyebrow">ENUMERATION EXTREMES</p><h2>最小p，与最大p。</h2><dl><div><dt>精确p 最小</dt><dd>{{result.exact_p.min.value.display}} <small>并列{{result.exact_p.min.tie_count}}个<template v-if="result.exact_p.min.value.underflow"> · double下溢</template></small></dd></div><div><dt>精确p 最大</dt><dd>{{result.exact_p.max.value.display}} <small>并列{{result.exact_p.max.tie_count}}个<template v-if="result.exact_p.max.value.underflow"> · double下溢</template></small></dd></div><div><dt>CMH 最小</dt><dd>{{fmt(result.cmh.min.value,6)}} <small>并列{{result.cmh.min.tie_count}}个</small></dd></div><div><dt>CMH 最大</dt><dd>{{fmt(result.cmh.max.value,6)}} <small>并列{{result.cmh.max.tie_count}}个</small></dd></div><div><dt>原研究p ≤ α</dt><dd>{{result.significance.baseline_below_alpha?'是':'否'}} · 修正后 {{result.significance.below_alpha_count}} 个组合 ≤ α</dd></div></dl><p>并列数以精确整数权重判定；示例最多保留{{result.capacity.example_cap}}个。</p></aside></div><h2 class="ruled-title">使方向翻转的修正</h2><div class="correction-grid"><CorrectionCard v-for="c in result.direction.examples" :key="'f'+c.ordinal" :correction="c"/></div><p v-if="!result.direction.examples.length" class="empty">在当前上限内没有组合翻转共同OR方向。</p><p v-else-if="result.direction.examples_truncated" class="plot-caption">仅展示前{{result.direction.examples.length}}个翻转组合，共{{result.direction.flip_count}}个；完整计数见CSV。</p><div class="correction-split"><section><h2 class="ruled-title">p 最小的修正</h2><CorrectionCard v-for="c in result.exact_p.min.examples" :key="'pmin'+c.ordinal" :correction="c"/></section><section><h2 class="ruled-title">p 最大的修正</h2><CorrectionCard v-for="c in result.exact_p.max.examples" :key="'pmax'+c.ordinal" :correction="c"/></section></div><aside class="interpretation-boundary"><b>口径与边界</b><p>{{result.interpretation}}</p><p>{{result.tail_rule}}</p><p>基线精确p {{result.baseline.exact_p.display}}、CMH {{fmt(result.baseline.cmh,6)}}，与原研究冻结结果一致；修正仅改变S=Σa与共同OR的分子/分母。</p><p v-if="result.baseline.alpha_tie">基线p与α在浮点末位并列，≤α标记沿用原研究记录；修正组合按精确整数权重以≤α判定。</p><code>{{result.fingerprint}}</code><RouterLink :to="'/notes?run='+detail.base_run_id+'&sensitivity='+detail.id">写入复验说明 →</RouterLink></aside></template></template></template>
